1	package com.example.rebate.service;
2	
3	import com.example.rebate.repo.ChargebackRequestRepository;
4	import com.example.rebate.support.FingerprintService;
5	import com.example.rebate.web.ConflictException;
6	import java.util.Map;
7	import org.springframework.stereotype.Service;
8	import org.springframework.transaction.annotation.Transactional;
9	
10	/**
11	 * 冲回写操作的 requestId 幂等编排（同事务语义）。
12	 *
13	 * <p>与旧入口的独立事务占坑不同，冲回写操作要求“业务、版本与幂等结果同事务”：占坑行在业务
14	 * 事务内插入，与业务变更一起提交；业务失败时整事务回滚，占坑行随之消失（失败不占键，可用同键
15	 * 或换键重试）。并发同键在主键上阻塞：先提交者完成占坑并回写结果，后来者读到的必是已提交的
16	 * 首次记录——指纹一致则回放首次冻结结果，不一致立即 409。</p>
17	 */
18	@Service
19	public class ChargebackIdempotency {
20	
21	    private final ChargebackRequestRepository records;
22	    private final FingerprintService fingerprints;
23	
24	    public ChargebackIdempotency(ChargebackRequestRepository records,
25	                                 FingerprintService fingerprints) {
26	        this.records = records;
27	        this.fingerprints = fingerprints;
28	    }
29	
30	    /**
31	     * 在同一事务内占坑、执行业务并回写结果。
32	     *
33	     * @param opType 操作类型（纳入结构化指纹）
34	     * @param requestId 幂等键
35	     * @param payload 全部业务字段（含路径变量、expectedVersion、集合与精确时刻）
36	     * @param action 首次执行的业务动作，与占坑同事务
37	     */
38	    @Transactional
39	    public IdempotentOutcome run(String opType, String requestId, Object payload,
40	                                 java.util.function.Supplier<ServiceResult> action) {
41	        String fp = fingerprints.fingerprint(opType, requestId, payload);
42	        boolean acquired = records.tryAcquire(requestId, opType, fp,
43	                java.time.Instant.now());
44	        if (!acquired) {
45	            Map<String, Object> existing = records.find(requestId);
46	            if (existing == null) {
47	                // 理论上不可达：插入失败必然存在已提交行。
48	                throw new ConflictException("requestId=" + requestId + " 并发处理异常");
49	            }
50	            if (!fp.equals(String.valueOf(existing.get("FINGERPRINT")))
51	                    && !fp.equals(String.valueOf(existing.get("fingerprint")))) {
52	                throw new ConflictException("requestId=" + requestId + " 已用于不同业务参数");
53	            }
54	            Object status = existing.get("RESPONSE_STATUS");
55	            if (status == null) {
56	                status = existing.get("response_status");
57	            }
58	            Object body = existing.get("RESPONSE_BODY");
59	            if (body == null) {
60	                body = existing.get("response_body");
61	            }
62	            return IdempotentOutcome.replay(((Number) status).intValue(), String.valueOf(body));
63	        }
64	        ServiceResult result = action.get();
65	        records.complete(requestId, result.status(), fingerprints.toJson(result.body()));
66	        return IdempotentOutcome.first(result.status(), result.body());
67	    }
68	}
