            assertEquals(1, jdbc.queryForObject(
                    "SELECT COUNT(*) FROM t_clawback_master_receipt", Integer.class));
            assertEquals(1, jdbc.queryForObject(
                    "SELECT COUNT(*) FROM t_clawback_allocation", Integer.class));
        } finally {
            pool.shutdownNow();
        }
    }
}

